package com.spendly.domain.shared;

import java.util.Objects;
import java.util.UUID;

/**
 * Typed identifier of a line of an expense report. Wrapping the {@link UUID} prevents passing an
 * identifier of another kind where this one is expected: the compiler rejects it.
 *
 * @param value the underlying UUID
 */
public record LineId(UUID value) {

  public LineId {
    Objects.requireNonNull(value, "value");
  }

  /** A new random identifier (UUID v4), generated by the domain rather than by the database. */
  public static LineId newId() {
    return new LineId(UUID.randomUUID());
  }

  /**
   * Parses the textual form of a UUID.
   *
   * @throws IllegalArgumentException if {@code value} is not a valid UUID
   */
  public static LineId of(String value) {
    return new LineId(UUID.fromString(Objects.requireNonNull(value, "value")));
  }

  @Override
  public String toString() {
    return value.toString();
  }
}
